var i=`dry-don-t-repeat-yourself`;var o=2;var n={en:[{id:`T002-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Composition builds behavior by combining focused collaborators, rather than relying on deep inheritance trees.`},{id:`B`,text:`SOLID groups five object-oriented design heuristics: single responsibility, open/closed, Liskov substitution, interface segregation, and dependency inversion.`},{id:`C`,text:`Design by Contract specifies preconditions, postconditions, and invariants for components.`},{id:`D`,text:`DRY means every piece of knowledge should have one authoritative representation.`}]},{id:`T002-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Prefer asking an object to perform an operation over traversing several objects and making decisions externally.`},{id:`B`,text:`SRP asks for one coherent reason to change; OCP prefers extension at stable variation points; LSP preserves behavioral contracts; ISP offers narrow consumer-oriented interfaces; DIP makes policy depend on abstractions rather than volatile implementations.`},{id:`C`,text:`Compare alternatives by number of components, states, exceptional paths, deployment steps, and cognitive overhead.`},{id:`D`,text:`Look for duplicated decisions, schemas, validations, calculations, or business invariants.`}]},{id:`T002-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A tax rule repeated in web, mobile, and backend can drift.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Define what happens on insufficient funds and ensure the operation is atomic.`},{id:`B`,text:`If pricing, authentication, and email templates all live there, cohesion suffers; if every other module writes its tables directly, coupling rises.`},{id:`C`,text:`It should still store currency explicitly if changing that later would corrupt historical amounts.`},{id:`D`,text:`Move the authoritative calculation server-side and expose a stable contract; client-side previews should be treated as provisional, not a competing source of truth.`}]},{id:`T002-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Premature DRY produces generic utilities with confusing flags and coupling between unrelated features.`},{id:`B`,text:`Composition can scatter behavior across too many objects, and indirection has a cost.`},{id:`C`,text:`Simplistic is not simple: ignoring authorization, error handling, or transaction boundaries creates hidden complexity.`},{id:`D`,text:`Different audiences have different expectations; conventions can evolve.`}]},{id:`T002-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Duplicate text is not always duplicate knowledge: two similar functions can embody separate business rules and deserve independent evolution.`}]}]},{id:`T002-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Any repeated line of code violates DRY, even when the business rules differ.`}]}]},{id:`T002-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`The 'rule of three' is a practical heuristic: observe real variation before extracting a shared component.`}]}]},{id:`T002-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Look for duplicated decisions, schemas, validations, calculations, or business invariants.`},{id:`B`,text:`Two independently evolving business rules should always be merged into one utility.`},{id:`C`,text:`DRY means every piece of knowledge should have one authoritative representation.`},{id:`D`,text:`SOLID requires an interface for every class, even when there is no variation.`}]},{id:`T002-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Any repeated line of code violates DRY, even when the business rules differ.`},{id:`B`,text:`The 'rule of three' is a practical heuristic: observe real variation before extracting a shared component.`},{id:`C`,text:`Move the authoritative calculation server-side and expose a stable contract; client-side previews should be treated as provisional, not a competing source of truth.`},{id:`D`,text:`KISS justifies skipping transaction boundaries when they complicate code.`}]},{id:`T002-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A tax rule repeated in web, mobile, and backend can drift.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Find duplicate discount rules across three modules, identify the true authoritative policy, propose a shared representation, and write tests showing what must remain different in each caller.`},{id:`B`,text:`Replace an exporter hierarchy with composed formatter and transport interfaces, while preserving public behavior. Compare change cost for adding one format and one destination.`},{id:`C`,text:`Design an MVP notification feature with no speculative queue. Ask the agent to enumerate failure modes, choose the minimum defensible architecture, and document triggers for scaling later.`},{id:`D`,text:`Audit a REST API and UI for misleading names and hidden side effects. Propose consistent behavior, write examples of expected error responses, and test retry semantics.`}]},{id:`T002-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`When does removing duplicate lines introduce a more dangerous duplication of assumptions?`}]}]},{id:`T002-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A tax rule repeated in web, mobile, and backend can drift.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T002-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A tax rule repeated in web, mobile, and backend can drift.`,b:!0},{t:` — propose three checks for `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T002-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A tax rule repeated in web, mobile, and backend can drift.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T002-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`DRY — Don't Repeat Yourself`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A tax rule repeated in web, mobile, and backend can drift.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T002-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`DRY — не дублюй знання`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Композиція формує поведінку з невеликих компонентів замість глибоких ієрархій спадкування.`},{id:`B`,text:`SOLID об’єднує п’ять принципів об’єктного проєктування: єдину відповідальність, відкритість/закритість, підстановку Лісков, розділення інтерфейсів та інверсію залежностей.`},{id:`C`,text:`Проєктування за контрактом визначає передумови, післяумови та інваріанти компонентів.`},{id:`D`,text:`DRY означає, що кожне правило або знання має одне авторитетне представлення.`}]},{id:`T002-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`DRY — не дублюй знання`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Краще просити об’єкт виконати дію, ніж проходити кілька вкладених об’єктів та ухвалювати рішення ззовні.`},{id:`B`,text:`SRP вимагає однієї узгодженої причини змін; OCP дозволяє розширення в точках варіативності; LSP зберігає поведінкові контракти; ISP пропонує вузькі інтерфейси; DIP відділяє політику від мінливих реалізацій.`},{id:`C`,text:`Порівнюйте варіанти за кількістю компонентів, станів, виняткових шляхів, кроків розгортання та когнітивним навантаженням.`},{id:`D`,text:`Шукайте повторення рішень, схем, валідації, розрахунків і бізнес-інваріантів.`}]},{id:`T002-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Правило податку, повторене у вебі, мобільному застосунку й бекенді, з часом розходиться.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Визначте поведінку за браку коштів і забезпечте атомарність операції.`},{id:`B`,text:`Якщо в ньому також ціни, авторизація й шаблони листів — згуртованість падає; якщо всі модулі пишуть прямо в його таблиці — зв’язність зростає.`},{id:`C`,text:`Але валюту варто зберігати явно, якщо інакше майбутні зміни пошкодять історичні суми.`},{id:`D`,text:`Перенесіть авторитетний розрахунок на сервер і надайте контракт; попередній розрахунок у клієнті вважайте орієнтовним.`}]},{id:`T002-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`DRY — не дублюй знання`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Передчасний DRY породжує універсальні утиліти з незрозумілими прапорцями й зв’язує незалежні фічі. «Правило трьох» — корисна евристика: спочатку побачте реальні варіації, потім узагальнюйте.`},{id:`B`,text:`Композиція іноді розпорошує поведінку між надто багатьма об’єктами й додає непрямість.`},{id:`C`,text:`Примітивність не дорівнює простоті: ігнорування авторизації, помилок чи транзакцій ховає складність.`},{id:`D`,text:`Різні аудиторії мають різні очікування, а конвенції змінюються.`}]},{id:`T002-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Однаковий текст не завжди є дублюванням знань: схожі функції можуть реалізовувати різні бізнес-правила, що змінюються незалежно.`}]}]},{id:`T002-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Будь-який повторений рядок коду порушує DRY, навіть коли бізнес-правила різні.`}]}]},{id:`T002-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Передчасний DRY породжує універсальні утиліти з незрозумілими прапорцями й зв’язує незалежні фічі. «Правило трьох» — корисна евристика: спочатку побачте реальні варіації, потім узагальнюйте.`}]}]},{id:`T002-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`DRY — не дублюй знання`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Шукайте повторення рішень, схем, валідації, розрахунків і бізнес-інваріантів.`},{id:`B`,text:`Два незалежні бізнес-правила завжди слід об’єднувати в одну утиліту.`},{id:`C`,text:`DRY означає, що кожне правило або знання має одне авторитетне представлення.`},{id:`D`,text:`SOLID вимагає інтерфейсу для кожного класу, навіть якщо немає варіативності.`}]},{id:`T002-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`DRY — не дублюй знання`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Будь-який повторений рядок коду порушує DRY, навіть коли бізнес-правила різні.`},{id:`B`,text:`Передчасний DRY породжує універсальні утиліти з незрозумілими прапорцями й зв’язує незалежні фічі. «Правило трьох» — корисна евристика: спочатку побачте реальні варіації, потім узагальнюйте.`},{id:`C`,text:`Перенесіть авторитетний розрахунок на сервер і надайте контракт; попередній розрахунок у клієнті вважайте орієнтовним.`},{id:`D`,text:`KISS виправдовує пропуск меж транзакцій, якщо вони ускладнюють код.`}]},{id:`T002-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Правило податку, повторене у вебі, мобільному застосунку й бекенді, з часом розходиться.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Знайдіть повторені правила знижок у трьох модулях, визначте авторитетну політику, запропонуйте спільне представлення й напишіть тести, які показують відмінності між викликами.`},{id:`B`,text:`Замініть ієрархію експортерів композицією форматера й транспорту, зберігши контракт. Порівняйте вартість додавання нового формату та нового сховища.`},{id:`C`,text:`Спроєктуйте MVP-сповіщення без гіпотетичної черги. Попросіть агента перелічити збої, обрати мінімально достатню архітектуру й визначити умови майбутнього масштабування.`},{id:`D`,text:`Перевірте REST API та UI на оманливі назви й приховані побічні ефекти. Запропонуйте узгоджену поведінку, приклади помилок і тести повторних запитів.`}]},{id:`T002-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Коли усунення однакових рядків створює небезпечніше дублювання припущень?`}]}]},{id:`T002-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Правило податку, повторене у вебі, мобільному застосунку й бекенді, з часом розходиться.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`DRY — не дублюй знання`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T002-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Правило податку, повторене у вебі, мобільному застосунку й бекенді, з часом розходиться.`,b:!0},{t:` запропонуйте три перевірки `},{t:`DRY — не дублюй знання`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T002-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Правило податку, повторене у вебі, мобільному застосунку й бекенді, з часом розходиться.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T002-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`DRY — не дублюй знання`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Правило податку, повторене у вебі, мобільному застосунку й бекенді, з часом розходиться.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:2,questions:n};export{s as default,n as questions,i as slug,o as topicId};